/**
 * Simulated market universe — everything you can buy in the game.
 *
 * EVERY price here is generated by the simulation engine; none of these
 * numbers are real market quotes. `basePrice` values are arbitrary simulation
 * anchors in CAD, documented here for transparency.
 *
 * The catalogue is data-driven: each "section" fixes the exchange, market and
 * asset class, then lists one row per listing. Adding a listing is one line.
 */

export type AssetClass = "STOCK" | "ETF" | "CRYPTO" | "COMMODITY" | "BOND";
export type Market = "US" | "CA" | "AADI";

export interface StockDef {
  symbol: string;
  name: string;
  exchange: string;
  market: Market;
  assetClass: AssetClass;
  sector: string;
  description: string;
  basePrice: number; // simulation anchor price in CAD
  drift: number; // fraction of base added/subtracted across the 50-day cycle
  vol: number; // volatility multiplier applied to the engine's waves
  seed: number; // hash anchor for deterministic per-day wobble
}

/** [symbol, name, sector, basePrice, drift, vol?] */
type Row = [string, string, string, number, number, number?];

interface Section {
  market: Market;
  assetClass: AssetClass;
  exchange: string;
  rows: Row[];
}

/** The house stock: every new player is gifted one share of this listing. */
export const HOUSE_STOCK = "AADIDEV";
export const HOUSE_STOCK_NAME = "Aadidev.co";

