/** Hand-written blurbs for the listings players are most likely to click. */
const DESCRIPTION_OVERRIDES: Record<string, string> = {
  AAPL: "Simulated listing: a large consumer-technology company known for smartphones, computers and digital services. In this simulation a single product launch can move it a lot.",
  AADIDEV:
    "The house listing of the AadiVerse: a scrappy fictional software company. Every new player is gifted one share, and it is famous for wild swings on fake rumours.",
  MAYHEM:
    "A fictional game studio that ships chaos for a living. Its price reacts to hype, delays and the occasional catastrophic bug.",
  GME: "Simulated listing: the original meme stock. Fundamentals are thin, crowd psychology is not.",
  AMC: "Simulated listing: a cinema chain that trades on vibes as much as earnings.",
  BTC: "Simulated crypto asset. Expect violent swings and 24/7 moves — perfect for practising position sizing.",
  GOLD: "Simulated gold price. Historically the classic 'hide from the storm' asset in this game's scenario engine.",
  CAN10Y: "Simulated Government of Canada 10-year bond. Tiny moves, steady — the boring-but-safe end of the market.",
  SPY: "Simulated S&P 500 index fund: one purchase, 500 companies' worth of diversification.",
  US10Y: "Simulated US Treasury. When crashes hit, money tends to hide here.",
  XEQT: "A simulated all-equity ETF — the classic 'just buy everything' starter position.",
};

function describe(
  name: string,
  sector: string,
  assetClass: AssetClass,
): string {
  switch (assetClass) {
    case "ETF":
      return `${name} — a simulated fund that holds a basket of ${sector.toLowerCase()} securities. One purchase, instant diversification.`;
    case "CRYPTO":
      return `${name} — a simulated crypto asset in the AadiVerse. Prices here are fictional and extremely volatile.`;
    case "COMMODITY":
      return `${name} — a simulated commodity price series. Commodities trade on supply, weather and geopolitics in this game.`;
    case "BOND":
      return `${name} — a simulated fixed-income instrument. Small moves, steady drift: the calm corner of the market.`;
    default:
      return `${name} — a simulated ${sector.toLowerCase()} company. Every price, headline and fundamental here is fictional education material.`;
  }
}

function buildSections(): StockDef[] {
  const out: StockDef[] = [];
  let seed = 11;
  for (const section of SECTIONS) {
    for (const [symbol, name, sector, basePrice, drift, vol] of section.rows) {
      seed += 6;
      out.push({
        symbol,
        name,
        exchange: section.exchange,
        market: section.market,
        assetClass: section.assetClass,
        sector,
        description:
          DESCRIPTION_OVERRIDES[symbol] ?? describe(name, sector, section.assetClass),
        basePrice,
        drift,
        vol: vol ?? VOL_BY_CLASS[section.assetClass],
        seed,
      });
    }
  }
  return out;
}

export const STOCKS: StockDef[] = buildSections();

const bySymbol = new Map(STOCKS.map((s) => [s.symbol, s]));

/**
 * Symbols that used to exist and may still sit in portfolios, orders or the
 * ledger (the tutorial stock was renamed when the app became Market Mayhem).
 * They resolve to their replacement so old holdings keep working.
 */
const LEGACY_SYMBOLS: Record<string, string> = {
  "AADI-DEMO": "AADIDEV",
};

export function canonicalSymbol(symbol: string): string {
  const upper = symbol.toUpperCase();
  return LEGACY_SYMBOLS[upper] ?? upper;
}

export function getStockDef(symbol: string): StockDef | undefined {
  return bySymbol.get(canonicalSymbol(symbol));
}

export function listStockDefs(): StockDef[] {
  return STOCKS;
}

/** Every sector present in the universe, in catalogue order. */
export function listSectors(): string[] {
  const seen: string[] = [];
  for (const s of STOCKS) if (!seen.includes(s.sector)) seen.push(s.sector);
  return seen;
}
